  "SELECT u.id, u.email, u.account_id FROM sessions s JOIN users u ON u.id = s.user_id WHERE s.token = $1 AND s.expires_at > now()",
  [req.cookies && req.cookies.session]
);
```

A soft-deleted account currently has zero effect: its users keep valid sessions, keep getting `req.user.accountId` set, and can still `POST /orders`, cancel orders, and (once the IDOR issue is fixed) still `PATCH` their own account — nothing anywhere checks `deleted_at`.

Fix it at that one chokepoint rather than scattering `deleted_at IS NULL` checks into each route — the comment above the middleware already states the invariant ("every request that reaches a route handler has passed through here"), so this is the natural place to enforce it:

```js
async function sessionUser(req, res, next) {
  const rows = await db.query(
    `SELECT u.id, u.email, u.account_id
     FROM sessions s
     JOIN users u ON u.id = s.user_id
     JOIN accounts a ON a.id = u.account_id
     WHERE s.token = $1 AND s.expires_at > now() AND a.deleted_at IS NULL`,
    [req.cookies && req.cookies.session]
  );
  if (!rows.length) return res.status(401).end();
  req.user = { id: rows[0].id, email: rows[0].email, accountId: rows[0].account_id };
  next();
